// Aggregate GitHub data into a single context object
const items = $input.all();

// Extract data from the three API calls
let commits = [];
let issues = [];
let prs = [];

for (const item of items) {
  const data = item.json;
  if (Array.isArray(data)) {
    for (const entry of data) {
      if (entry.sha && entry.commit) {
        commits.push({
          sha: entry.sha.substring(0, 7),
          message: entry.commit.message.split('\n')[0],
          author: entry.commit.author?.name || entry.author?.login || 'unknown',
          date: entry.commit.author?.date
        });
      } else if (entry.pull_request && entry.merged_at) {
        prs.push({
          number: entry.number,
          title: entry.title,
          author: entry.user?.login,
          merged_at: entry.merged_at
        });
      } else if (entry.number && !entry.pull_request) {
        issues.push({
          number: entry.number,
          title: entry.title,
          closed_at: entry.closed_at,
          labels: (entry.labels || []).map(l => l.name)
        });
      }
    }
  }
}

// Filter PRs to only merged ones from last 7 days
const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
prs = prs.filter(pr => new Date(pr.merged_at) > weekAgo);

const repo = $env.GITHUB_REPO || 'owner/repo';
const lang = $env.SUMMARY_LANGUAGE || 'EN';

return [{
  json: {
    repo,
    lang,
    week_ending: new Date().toISOString().split('T')[0],
    stats: {
      total_commits: commits.length,
      total_issues_closed: issues.length,
      total_prs_merged: prs.length
    },
    commits: commits.slice(0, 50),
    issues_closed: issues.slice(0, 30),
    prs_merged: prs.slice(0, 30)
  }
}];

// Extract the text from Claude's response
const response = $input.first().json;
const content = response.content || [];
const text = content
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n');

const repo = $env.GITHUB_REPO || 'owner/repo';
const weekEnding = new Date().toISOString().split('T')[0];

return [{
  json: {
    subject: `📊 Weekly Dev Summary — ${repo} (${weekEnding})`,
    markdown: text,
    html: text
      .replace(/^### (.*$)/gim, '<h3>$1</h3>')
      .replace(/^## (.*$)/gim, '<h2>$1</h2>')
      .replace(/^# (.*$)/gim, '<h1>$1</h1>')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/^- (.*$)/gim, '<li>$1</li>')
      .replace(/\n/g, '<br>')
  }
}];
